def dfs(graph, start):
    visited = []
    seen = set()
    stack = [start]
    while stack:
        node = stack.pop()
        if node in seen:
            continue
        seen.add(node)
        visited.append(node)
        for nbr in reversed(graph.get(node, [])):
            if nbr not in seen:
                stack.append(nbr)
    return visited

