def test_dfs(self):
    g = {'a': ['b', 'c'], 'b': ['a', 'd'], 'c': ['a'], 'd': ['b']}
    order = dfs(g, 'a')
    self.assertEqual(order[0], 'a')
    self.assertEqual(set(order), {'a', 'b', 'c', 'd'})

