from collections import deque

def bfs(graph, start):
    visited = []
    seen = {start}
    q = deque([start])
    while q:
        node = q.popleft()
        visited.append(node)
        for nbr in graph.get(node, []):
            if nbr not in seen:
                seen.add(nbr)
                q.append(nbr)
    return visited

