from collections import deque

def shortest_path_length(graph, start, goal):
    if start == goal:
        return 0
    seen = {start}
    q = deque([(start, 0)])
    while q:
        node, dist = q.popleft()
        for nbr in graph.get(node, []):
            if nbr in seen:
                continue
            if nbr == goal:
                return dist + 1
            seen.add(nbr)
            q.append((nbr, dist + 1))
    return -1

