from collections import deque

def is_connected(graph):
    if not graph:
        return True
    start = next(iter(graph))
    seen = {start}
    q = deque([start])
    while q:
        node = q.popleft()
        for nbr in graph.get(node, []):
            if nbr not in seen:
                seen.add(nbr)
                q.append(nbr)
    return len(seen) == len(graph)
